<?php declare(strict_types=1); use FastWebsite\Core\View; $value=static fn(string $field):string=>(string)($values[$field]??''); $editing=is_int($themeId); ?>
<section class="admin-page-heading"><div><p class="eyebrow"><?=$editing?'Theme revision':'New taxonomy item'?></p><h1><?=$editing?'Edit research theme':'Create research theme'?></h1><p>The lead department controls editor scope; published themes become assignable to projects and publications.</p></div><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/metadata#themes">Cancel</a></section>
<?php if ($errors !== []): ?><div class="form-alert"><strong>Please correct the following:</strong><ul><?php foreach ($errors as $error): ?><li><?=View::escape($error)?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form class="content-form" method="post" action="<?=View::escape($baseUrl)?>admin/research/metadata/themes<?=$editing?'/'.$themeId:''?>"><input type="hidden" name="_token" value="<?=View::escape($csrfToken)?>">
<section class="form-section"><div class="form-section-heading"><h2>Theme identity</h2></div><div class="form-grid"><div class="form-field span-2"><label for="name">Theme name *</label><input id="name" name="name" maxlength="200" required value="<?=View::escape($value('name'))?>"></div><div class="form-field span-2"><label for="slug">URL name</label><input id="slug" name="slug" maxlength="220" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" value="<?=View::escape($value('slug'))?>"><p class="field-guidance">Leave blank to generate it from the theme name.</p></div><div class="form-field"><label for="department_id">Lead department *</label><select id="department_id" name="department_id" required><?php foreach ($departments as $department): ?><option value="<?=(int)$department['id']?>"<?=$value('department_id')===(string)$department['id']?' selected':''?>><?=View::escape($department['name'])?></option><?php endforeach; ?></select></div><div class="form-field"><label for="parent_theme_id">Parent theme</label><select id="parent_theme_id" name="parent_theme_id"><option value="">Top-level theme</option><?php foreach ($parentThemes as $theme): ?><option value="<?=(int)$theme['id']?>"<?=$value('parent_theme_id')===(string)$theme['id']?' selected':''?>><?=View::escape($theme['name'])?></option><?php endforeach; ?></select></div><div class="form-field"><label for="icon">Icon reference</label><input id="icon" name="icon" maxlength="100" value="<?=View::escape($value('icon'))?>" placeholder="Optional icon name"></div><div class="form-field"><label for="display_order">Display order</label><input id="display_order" name="display_order" type="number" min="0" max="65535" value="<?=View::escape($value('display_order'))?>"></div><div class="form-field span-2"><label for="description">Description</label><textarea id="description" name="description" rows="7"><?=View::escape($value('description'))?></textarea></div></div></section>
<div class="form-actions"><button class="button <?=$canPublish&&$currentStatus!=='published'?'button-secondary':'button-primary'?>" type="submit" name="submit_action" value="save"><?=$currentStatus==='published'?'Save published changes':'Save draft'?></button><?php if ($canPublish && $currentStatus !== 'published'): ?><button class="button button-primary" type="submit" name="submit_action" value="publish">Save and publish</button><?php endif; ?><a class="button button-secondary" href="<?=View::escape($baseUrl)?>admin/research/metadata#themes">Cancel</a></div></form>
